        get filteredTransactions() {
            const q = this.searchQuery.trim().toLowerCase();
            if (!q) return this.transactions.slice(0, 5);
            return this.transactions.filter(item => item.name.toLowerCase().includes(q));
        },
        get pages() {
            const cp = this.currentPage;
            const tp = this.totalPages;
            if (tp <= 7) return Array.from({ length: tp }, (_, i) => i + 1);
            if (cp <= 4) return [1, 2, 3, 4, 5, 'ellipsis-end', tp];
            if (cp >= tp - 3) return [1, 'ellipsis-start', tp - 4, tp - 3, tp - 2, tp - 1, tp];
            return [1, 'ellipsis-start', cp - 1, cp, cp + 1, 'ellipsis-end', tp];
        },
        goPrevious() {
            if (this.currentPage > 1) this.currentPage--;
        },
        goNext() {
            if (this.currentPage < this.totalPages) this.currentPage++;
        },
        goTo(page) {
            if (typeof page === 'number') this.currentPage = page;
        },
        linkClass(item) {
            return this.currentPage === item ? this.paginationClasses.linkActive : this.paginationClasses.link;
        },
        prevClass() {
            return this.currentPage <= 1 ? this.paginationClasses.prevDisabled : this.paginationClasses.prev;
        },
        nextClass() {
            return this.currentPage >= this.totalPages ? this.paginationClasses.nextDisabled : this.paginationClasses.next;
        }
    }"
